'use strict';
(()=>{
  const STORE='franklinNavigator.assistantPractical.v1',MAX=10;
  const isEs=()=>String(document.documentElement.lang||'').toLowerCase().startsWith('es');
  const tx=(en,es)=>isEs()?es:en;
  const clean=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\s'-]/g,' ').replace(/\s+/g,' ').trim();
  const safeHref=h=>typeof h==='string'&&h.startsWith('/')&&!h.startsWith('//')&&!/[<>"\\]/.test(h);
  const TASKS={
    business:{
      match:/\b(start|starting|open|opening|launch|new|iniciar|abrir|empezar)\b.*\b(business|negocio|empresa)\b|\b(business license|licencia comercial|licencia de negocio)\b/,
      title:['Start a Franklin business — practical checklist','Iniciar un negocio en Franklin — lista práctica'],
      intro:['First, narrow the setup. Franklin Navigator can organize the order, but changing license, zoning, permit, fee and eligibility details must be confirmed at the linked current source before you act.','Primero, precisa el tipo de negocio. Franklin Navigator puede organizar el orden, pero debes confirmar en la fuente actual enlazada los requisitos cambiantes de licencias, zonificación, permisos, tarifas y elegibilidad antes de actuar.'],
      question:['Which setup is closest?','¿Qué tipo de situación se parece más a la tuya?'],
      variants:{home:['Home-based','Desde casa'],location:['New or leased location','Local nuevo o alquilado'],existing:['Existing business / change','Negocio existente / cambio']},
      detect:[[/(home|house|from home|home based|desde casa|en casa)/,'home'],[/(location|storefront|lease|leased|office|shop|local|alquilado|arrendado|tienda|oficina)/,'location'],[/(existing|already|change|move my business|existente|ya tengo|cambio|mudar mi negocio)/,'existing']],
      steps:{
        common:[
          ['goal',['Write down the activity, business name you plan to use, and the address or area involved. Keep private financial and identity details out of the Assistant.','Anota la actividad, el nombre comercial que planeas usar y la dirección o zona relacionada. No incluyas datos privados financieros ni de identidad en el Asistente.'],'/local-pathways/start-run-business/'],
          ['requirements',['Use the Franklin business pathway to identify which local, county or state questions apply, then confirm each changing requirement at the original source linked there.','Usa la ruta empresarial de Franklin para identificar qué preguntas locales, del condado o estatales corresponden y confirma cada requisito cambiante en la fuente original enlazada allí.'],'/local-pathways/start-run-business/'],
          ['license',['Work through the business-license checklist and note what you still need before submitting or paying anywhere.','Sigue la lista de licencia comercial y anota qué te falta antes de presentar algo o pagar en cualquier sitio.'],'/get-it-done/#business-license']
        ],
        home:[['home-check',['Before relying on a home address for the business, verify the current zoning, permit or use rules that apply to that address and activity.','Antes de usar una dirección residencial para el negocio, verifica las reglas actuales de zonificación, permisos o uso aplicables a esa dirección y actividad.'],'/address-lookup/?topic=permit']],
        location:[['location-check',['Before signing or relying on a location, verify the current zoning/permit path for that address and intended activity.','Antes de firmar o depender de un local, verifica la ruta actual de zonificación/permisos para esa dirección y actividad.'],'/address-lookup/?topic=permit']],
        existing:[['change-check',['List what is changing—name, location, activity or ownership—and use the business pathway to verify which filings or permits need an update.','Anota qué cambia—nombre, ubicación, actividad o propiedad—y usa la ruta empresarial para verificar qué registros o permisos necesitan actualización.'],'/local-pathways/start-run-business/']]
      }
    },
    permit:{
      match:/\b(permit|remodel|addition|fence|deck|zoning|permiso|remodelacion|ampliacion|cerca|terraza|zonificacion)\b/,
      title:['Franklin permit project — practical checklist','Proyecto con permiso en Franklin — lista práctica'],
      intro:['Organize the project before relying on any requirement. Permit, zoning, inspection, fee and timing details can change, so confirm them at the responsible source linked by Franklin Navigator.','Organiza el proyecto antes de depender de cualquier requisito. Los permisos, zonificación, inspecciones, tarifas y plazos pueden cambiar; confírmalos en la fuente responsable enlazada por Franklin Navigator.'],
      question:['What kind of project are you planning?','¿Qué tipo de proyecto planeas?'],
      variants:{home:['Home alteration','Cambio en vivienda'],business:['Business location / use','Local o uso comercial'],unsure:['Not sure yet','Aún no estoy seguro']},
      detect:[[/(business|commercial|store|office|negocio|comercial|tienda|oficina)/,'business'],[/(home|house|fence|deck|remodel|addition|casa|vivienda|cerca|terraza|remodelacion|ampliacion)/,'home']],
      steps:{common:[['scope',['Write down the project type and property address without putting private documents into the Assistant.','Anota el tipo de proyecto y la dirección de la propiedad sin poner documentos privados en el Asistente.'],'/permits-home/'],['lookup',['Use the address-specific permit/zoning lookup to find the responsible current source.','Usa la búsqueda específica de permisos/zonificación por dirección para encontrar la fuente actual responsable.'],'/address-lookup/?topic=permit'],['prepare',['Use the project planner to organize questions, documents and next actions before contacting the responsible office.','Usa el planificador del proyecto para organizar preguntas, documentos y próximos pasos antes de contactar a la oficina responsable.'],'/permits-home/']],home:[],business:[['business-path',['If the project affects a business opening or operation, also check the business-start pathway so licensing and location questions stay connected.','Si el proyecto afecta la apertura u operación de un negocio, revisa también la ruta de inicio empresarial para mantener conectadas las preguntas de licencia y ubicación.'],'/local-pathways/start-run-business/']],unsure:[]}
    }
  };
  let session=null,storageIssue=false;
  const detectTask=raw=>{const t=clean(raw);for(const [id,task] of Object.entries(TASKS))if(task.match.test(t))return id;return session?.taskId||null};
  const detectVariant=(taskId,raw)=>{const task=TASKS[taskId],t=clean(raw);for(const [rx,v] of task.detect||[])if(rx.test(t))return v;return session?.taskId===taskId?session.variant:null};
  const stepsFor=(taskId,variant)=>{const t=TASKS[taskId];return [...t.steps.common,...(t.steps[variant]||[])].slice(0,5)};
  const read=()=>{storageIssue=false;try{const raw=localStorage.getItem(STORE)||'[]';if(raw.length>150000)throw Error();const v=JSON.parse(raw);if(!Array.isArray(v))throw Error();const out=[];for(const p of v.slice(0,MAX)){if(!p||p.schema!=='franklin.assistant-practical.v1'||!TASKS[p.taskId]||typeof p.id!=='string'||!/^fp-[a-z0-9-]{1,80}$/i.test(p.id))continue;const variant=Object.hasOwn(TASKS[p.taskId].variants,p.variant)?p.variant:null;if(!variant)continue;out.push({schema:p.schema,id:p.id,taskId:p.taskId,variant,savedAt:typeof p.savedAt==='string'?p.savedAt:'',privacy:{rawQuestionStored:false,freeNarrativeStored:false,networkSubmission:false}})}if(out.length!==v.length)storageIssue=true;return out}catch{storageIssue=true;return []}};
  const write=rows=>{if(storageIssue)return false;try{const text=JSON.stringify(rows.slice(0,MAX));localStorage.setItem(STORE,text);return localStorage.getItem(STORE)===text}catch{return false}};
  const save=(taskId,variant)=>{const rows=read();if(storageIssue||rows.length>=MAX)return false;rows.unshift({schema:'franklin.assistant-practical.v1',id:`fp-${Date.now()}-${Math.random().toString(16).slice(2,7)}`,taskId,variant,savedAt:new Date().toISOString(),privacy:{rawQuestionStored:false,freeNarrativeStored:false,networkSubmission:false}});return write(rows)};
  const addLink=(actions,label,href,primary=false)=>{if(!safeHref(href))return;const a=document.createElement('a');a.className='button'+(primary?' primary':'');a.href=href;a.textContent=label;actions.append(a)};
  function renderPlan(root,taskId,variant,{saved=false}={}){
    const task=TASKS[taskId];if(!task||!variant)return;
    root.replaceChildren();root.hidden=false;root.dataset.franklinNativeLocale='';
    const article=document.createElement('article');article.className='navigator-result r40-practical-plan';
    const h=document.createElement('h3');h.textContent=task.title[isEs()?1:0];const intro=document.createElement('p');intro.textContent=task.intro[isEs()?1:0];article.append(h,intro);
    const badge=document.createElement('p');badge.className='fine-print';badge.textContent=tx(`Plan type: ${task.variants[variant][0]}`,`Tipo de plan: ${task.variants[variant][1]}`);article.append(badge);
    const ol=document.createElement('ol');ol.className='check-list';for(const [id,text,href] of stepsFor(taskId,variant)){const li=document.createElement('li');li.dataset.stepId=id;const p=document.createElement('span');p.textContent=text[isEs()?1:0]+' ';li.append(p);const a=document.createElement('a');a.href=href;a.textContent=tx('Open this step','Abrir este paso');li.append(a);ol.append(li)}article.append(ol);
    const note=document.createElement('p');note.className='fine-print';note.textContent=tx('This checklist organizes the task; it does not confirm approval, eligibility, fees, deadlines or availability. Confirm changing details at the linked responsible source.','Esta lista organiza la tarea; no confirma aprobación, elegibilidad, tarifas, plazos ni disponibilidad. Confirma los datos cambiantes en la fuente responsable enlazada.');article.append(note);
    const actions=document.createElement('div');actions.className='actions';if(!saved){const b=document.createElement('button');b.type='button';b.className='button primary';b.textContent=tx('Save this checklist on this device','Guardar esta lista en este dispositivo');const status=document.createElement('span');status.className='fine-print';status.setAttribute('aria-live','polite');b.addEventListener('click',()=>{status.textContent=save(taskId,variant)?tx('Saved on this device. Your question was not saved.','Guardado en este dispositivo. Tu pregunta no se guardó.'):tx('This browser did not allow saving. The checklist is still usable here.','Este navegador no permitió guardar. La lista sigue disponible aquí.');renderSaved()});actions.append(b,status)}addLink(actions,tx('Open My Franklin','Abrir Mi Franklin'),isEs()?'/es/mi-franklin/#assistant-next-steps':'/my-franklin/#assistant-next-steps');article.append(actions);root.append(article);root.focus?.();
  }
  function renderClarify(root,taskId){const task=TASKS[taskId];root.replaceChildren();root.hidden=false;root.dataset.franklinNativeLocale='';const article=document.createElement('article');article.className='navigator-result r40-practical-clarify';const h=document.createElement('h3');h.textContent=task.title[isEs()?1:0];const p=document.createElement('p');p.textContent=task.question[isEs()?1:0];const actions=document.createElement('div');actions.className='actions';for(const [v,label] of Object.entries(task.variants)){const b=document.createElement('button');b.type='button';b.className='button';b.textContent=label[isEs()?1:0];b.addEventListener('click',()=>{session={taskId,variant:v};renderPlan(root,taskId,v)});actions.append(b)}article.append(h,p,actions);root.append(article)}
  function enhance(raw){const host=document.querySelector('[data-r40-practical]');if(!host)return;const taskId=detectTask(raw);if(!taskId){host.replaceChildren();host.hidden=true;return}const variant=detectVariant(taskId,raw);session={taskId,variant};variant?renderPlan(host,taskId,variant):renderClarify(host,taskId)}
  function renderSaved(){document.querySelectorAll('[data-r40-practical-saved]').forEach(root=>{root.replaceChildren();root.dataset.franklinNativeLocale='';const rows=read();if(storageIssue){const p=document.createElement('p');p.setAttribute('role','status');p.textContent=tx('Some saved checklist data could not be read. Nothing was deleted.','No se pudieron leer algunos datos de listas guardadas. No se eliminó nada.');root.append(p)}if(!rows.length){const p=document.createElement('p');p.className='empty-state';p.textContent=tx('No detailed Assistant checklists saved yet.','Todavía no hay listas detalladas del Asistente guardadas.');root.append(p);return}const grid=document.createElement('div');grid.className='grid three';for(const row of rows){const card=document.createElement('article');card.className='card';const h=document.createElement('h3');h.textContent=TASKS[row.taskId].title[isEs()?1:0];const p=document.createElement('p');p.textContent=TASKS[row.taskId].variants[row.variant][isEs()?1:0];const actions=document.createElement('div');actions.className='actions';const open=document.createElement('a');open.className='button small';open.href=(isEs()?'/es/asistente/':'/assistant/')+'?reopen='+encodeURIComponent(row.id);open.textContent=tx('Reopen checklist','Reabrir lista');const rm=document.createElement('button');rm.type='button';rm.className='button small';rm.textContent=tx('Remove','Quitar');rm.addEventListener('click',()=>{const now=read();if(!storageIssue&&write(now.filter(x=>x.id!==row.id)))renderSaved()});actions.append(open,rm);card.append(h,p,actions);grid.append(card)}root.append(grid)})}
  function mount(){
    document.querySelectorAll('[data-navigator-bot]').forEach(bot=>{if(bot.dataset.r40Mounted)return;bot.dataset.r40Mounted='1';const output=bot.querySelector('[data-navigator-output]'),form=bot.querySelector('form'),input=bot.querySelector('[data-navigator-input]');if(!output||!form||!input)return;const host=document.createElement('section');host.dataset.r40Practical='';host.hidden=true;host.tabIndex=-1;output.insertAdjacentElement('afterend',host);form.addEventListener('submit',()=>setTimeout(()=>enhance(input.value),0));bot.querySelectorAll('[data-navigator-example]').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>enhance(input.value),0)));const observer=new MutationObserver(()=>{if(!host.hidden||input.value.trim())setTimeout(()=>enhance(input.value),0)});observer.observe(output,{childList:true,subtree:true});const id=new URLSearchParams(location.search).get('reopen');if(id){const row=read().find(x=>x.id===id);if(row){session={taskId:row.taskId,variant:row.variant};renderPlan(host,row.taskId,row.variant,{saved:true})}}
      const saved=document.createElement('section');saved.className='r38-assistant-save';saved.dataset.r40PracticalSaved='';const sh=document.createElement('h3');sh.textContent=tx('Saved detailed checklists','Listas detalladas guardadas');saved.append(sh);host.insertAdjacentElement('afterend',saved);
    });
    document.querySelectorAll('[data-r38-assistant-plans]').forEach(old=>{if(old.parentElement?.querySelector('[data-r40-practical-saved]'))return;const saved=document.createElement('div');saved.dataset.r40PracticalSaved='';const h=document.createElement('h3');h.textContent=tx('Detailed Assistant checklists','Listas detalladas del Asistente');old.insertAdjacentElement('afterend',h);h.insertAdjacentElement('afterend',saved)});
    renderSaved();
  }
  document.readyState==='loading'?document.addEventListener('DOMContentLoaded',mount):mount();
  window.addEventListener('franklinlanguagechange',()=>{renderSaved();if(session){const host=document.querySelector('[data-r40-practical]');if(host&&session.variant)renderPlan(host,session.taskId,session.variant)}});
  window.FranklinR40Practical=Object.freeze({read,enhance,stepsFor,version:'FR-NAV1.15.0-HF2.4-CANDIDATE'});
})();
